  "inlineSchema": "datasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum UserRole {\n  USER\n  ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n}\n\nenum MeetingStatus {\n  SCHEDULED\n  LIVE\n  ENDED\n}\n\nenum ParticipantRole {\n  HOST\n  CO_HOST\n  PARTICIPANT\n}\n\nenum ParticipantStatus {\n  WAITING\n  ADMITTED\n  REJECTED\n  LEFT\n}\n\nenum RecordingStatus {\n  PROCESSING\n  READY\n  FAILED\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELED\n  PAST_DUE\n  TRIALING\n}\n\nenum TicketStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum TicketPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nmodel User {\n  id                  String     @id @default(uuid())\n  email               String     @unique\n  password            String\n  fullName            String\n  avatarUrl           String?    @db.Text\n  role                UserRole   @default(USER)\n  status              UserStatus @default(ACTIVE)\n  isVerified          Boolean    @default(true)\n  personalMeetingCode String     @unique\n  createdAt           DateTime   @default(now())\n  updatedAt           DateTime   @updatedAt\n\n  meetings            Meeting[]            @relation(\"HostedMeetings\")\n  participations      MeetingParticipant[]\n  recordings          Recording[]\n  subscriptions       UserSubscription[]\n  auditLogs           AuditLog[]\n  supportTickets      SupportTicket[]\n  organizationMembers OrganizationMember[]\n\n  @@index([email])\n  @@index([personalMeetingCode])\n}\n\nmodel Organization {\n  id        String   @id @default(uuid())\n  name      String\n  slug      String   @unique\n  ownerId   String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  members OrganizationMember[]\n}\n\nmodel OrganizationMember {\n  id             String   @id @default(uuid())\n  organizationId String\n  userId         String\n  role           String   @default(\"MEMBER\")\n  createdAt      DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, userId])\n}\n\nmodel Meeting {\n  id                      String        @id @default(uuid())\n  code                    String        @unique // format: abc-defg-hij\n  title                   String\n  description             String?       @db.Text\n  hostId                  String\n  scheduledAt             DateTime?\n  durationMinutes         Int           @default(60)\n  passcode                String?\n  isLocked                Boolean       @default(false)\n  isWaitingRoom           Boolean       @default(false)\n  isScreenShareRestricted Boolean       @default(false)\n  isChatRestricted        Boolean       @default(false)\n  status                  MeetingStatus @default(SCHEDULED)\n  startedAt               DateTime?\n  endedAt                 DateTime?\n  createdAt               DateTime      @default(now())\n  updatedAt               DateTime      @updatedAt\n\n  host         User                 @relation(\"HostedMeetings\", fields: [hostId], references: [id], onDelete: Cascade)\n  participants MeetingParticipant[]\n  invitations  MeetingInvitation[]\n  chatMessages ChatMessage[]\n  recordings   Recording[]\n\n  @@index([code])\n  @@index([hostId])\n  @@index([status])\n}\n\nmodel MeetingParticipant {\n  id           String            @id @default(uuid())\n  meetingId    String\n  userId       String?\n  guestName    String\n  guestEmail   String?\n  role         ParticipantRole   @default(PARTICIPANT)\n  status       ParticipantStatus @default(ADMITTED)\n  isMuted      Boolean           @default(false)\n  isVideoOff   Boolean           @default(false)\n  isHandRaised Boolean           @default(false)\n  joinedAt     DateTime          @default(now())\n  leftAt       DateTime?\n\n  meeting Meeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  user    User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([meetingId])\n  @@index([userId])\n}\n\nmodel MeetingInvitation {\n  id        String   @id @default(uuid())\n  meetingId String\n  email     String\n  status    String   @default(\"PENDING\") // PENDING, ACCEPTED, DECLINED\n  createdAt DateTime @default(now())\n\n  meeting Meeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n\n  @@index([meetingId])\n  @@index([email])\n}\n\nmodel ChatMessage {\n  id           String   @id @default(uuid())\n  meetingId    String\n  senderId     String?\n  senderName   String\n  senderAvatar String?  @db.Text\n  content      String   @db.Text\n  isPrivate    Boolean  @default(false)\n  recipientId  String?\n  createdAt    DateTime @default(now())\n\n  meeting Meeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n\n  @@index([meetingId])\n  @@index([recipientId])\n}\n\nmodel Recording {\n  id              String          @id @default(uuid())\n  meetingId       String\n  hostId          String\n  title           String\n  fileUrl         String          @db.Text\n  storageKey      String?\n  fileSize        BigInt          @default(0)\n  durationSeconds Int             @default(0)\n  status          RecordingStatus @default(READY)\n  createdAt       DateTime        @default(now())\n\n  meeting Meeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  host    User    @relation(fields: [hostId], references: [id], onDelete: Cascade)\n\n  @@index([meetingId])\n  @@index([hostId])\n}\n\nmodel SubscriptionPlan {\n  id                 String   @id @default(uuid())\n  name               String\n  code               String   @unique // FREE, PRO, BUSINESS\n  priceMonthly       Int      @default(0) // in USD cents e.g. 1200 = $12\n  priceYearly        Int      @default(0)\n  maxDurationMinutes Int      @default(45)\n  maxParticipants    Int      @default(100)\n  cloudRecording     Boolean  @default(false)\n  maxStorageMB       Int      @default(500)\n  featuresJson       String   @db.Text\n  isActive           Boolean  @default(true)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  subscriptions UserSubscription[]\n}\n\nmodel UserSubscription {\n  id                   String             @id @default(uuid())\n  userId               String\n  planId               String\n  status               SubscriptionStatus @default(ACTIVE)\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  currentPeriodStart   DateTime?\n  currentPeriodEnd     DateTime?\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n\n  user User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  plan SubscriptionPlan @relation(fields: [planId], references: [id], onDelete: Restrict)\n\n  @@index([userId])\n  @@index([planId])\n}\n\nmodel AuditLog {\n  id           String   @id @default(uuid())\n  userId       String?\n  action       String\n  resourceType String\n  resourceId   String?\n  ipAddress    String?\n  userAgent    String?  @db.Text\n  detailsJson  String?  @db.Text\n  createdAt    DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n}\n\nmodel SupportTicket {\n  id        String         @id @default(uuid())\n  userId    String?\n  email     String\n  subject   String\n  message   String         @db.Text\n  status    TicketStatus   @default(OPEN)\n  priority  TicketPriority @default(MEDIUM)\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([status])\n}\n",
